using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer()
    .WithTools<MyTools>()
    .WithResources<MyResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

[McpServerToolType]
public static class MyTools
{
    [McpServerTool(Name = "greet"), Description("Greets a user by name")]
    public static string Greet(string name) => $"Hello, {name}!";

    [McpServerTool(Name = "add"), Description("Adds two numbers")]
    public static double Add(double a, double b) => a + b;
}

[McpServerResourceType]
public static class MyResources
{
    [McpServerResource(ResourceUri = "config://app/settings",
        Name = "App Settings",
        Description = "Returns the current application configuration",
        MimeType = "application/json")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30
        };

        return System.Text.Json.JsonSerializer.Serialize(config, new System.Text.Json.JsonSerializerOptions
        {
            WriteIndented = true
        });
    }

    [McpServerResource(ResourceUri = "config://app/features",
        Name = "Feature Flags",
        Description = "Returns current feature flag settings",
        MimeType = "application/json")]
    public static string GetFeatureFlags()
    {
        var features = new
        {
            DarkMode = true,
            BetaAccess = false,
            NewDashboard = true
        };

        return System.Text.Json.JsonSerializer.Serialize(features, new System.Text.Json.JsonSerializerOptions
        {
            WriteIndented = true
        });
    }
}

